export declare const sunsetFilmTheme = "/* \u843D\u65E5\u80F6\u7247\u98CE\u683C */\n#wemd {\n    padding: 5px 22px;\n    max-width: 677px;\n    margin: 0 auto;\n    /* \u5F3A\u5236\u4F7F\u7528\u886C\u7EBF\u4F53\uFF0C\u8425\u9020\u7535\u5F71\u5B57\u5E55\u611F */\n    font-family: \"Songti SC\", \"SimSun\", \"STSong\", \"Georgia\", serif;\n    color: #4A3B32;\n    /* \u6DF1\u5496\u5561\u8272\u6587\u5B57\uFF0C\u6BD4\u9ED1\u8272\u66F4\u67D4\u548C */\n    background-color: transparent;\n    /* \u900F\u660E\u80CC\u666F\uFF0C\u517C\u5BB9\u5FAE\u4FE1\u6DF1\u8272\u6A21\u5F0F */\n    word-break: break-word;\n}\n\n/* \u6BB5\u843D - \u50CF\u662F\u5728\u8BFB\u4E00\u5C01\u65E7\u4FE1 */\n#wemd p {\n    margin-top: 26px;\n    margin-bottom: 26px;\n    line-height: 1.9;\n    letter-spacing: 0.8px;\n    /* \u5B57\u95F4\u8DDD\u7A0D\u5927 */\n    text-align: justify;\n    color: #5D4037;\n    font-size: 16px;\n}\n\n/* \n * \u4E00\u7EA7\u6807\u9898 - \u7535\u5F71\u7247\u540D\u98CE\u683C\n * \u4E0A\u4E0B\u53CC\u7EBF\u88C5\u9970\n */\n#wemd h1 {\n    margin-top: 60px;\n    margin-bottom: 50px;\n    text-align: center;\n    border-top: 4px double #B33D25;\n    /* \u53CC\u5B9E\u7EBF */\n    border-bottom: 1px solid #B33D25;\n    padding: 20px 0;\n}\n\n#wemd h1 .content {\n    font-size: 26px;\n    font-weight: 900;\n    color: #B33D25;\n    display: inline-block;\n    line-height: 1.2;\n    letter-spacing: 3px;\n}\n\n#wemd h1 .prefix,\n#wemd h1 .suffix {\n    display: none;\n}\n\n/* \n * \u4E8C\u7EA7\u6807\u9898 - \u90AE\u7968/\u6807\u7B7E\u98CE\u683C\n * \u5B9E\u5FC3\u80CC\u666F + \u767D\u5B57\n */\n#wemd h2 {\n    margin-top: 50px;\n    margin-bottom: 30px;\n    text-align: left;\n}\n\n#wemd h2 .content {\n    display: inline-block;\n    font-size: 19px;\n    font-weight: bold;\n    color: #FFFBF0;\n    /* \u7C73\u767D\u5B57 */\n    background-color: #B33D25;\n    /* \u9676\u571F\u7EA2\u5E95 */\n    padding: 8px 16px;\n    border-radius: 2px;\n    box-shadow: 4px 4px 0px rgba(179, 61, 37, 0.2);\n    /* \u6DE1\u6DE1\u7684\u590D\u53E4\u9634\u5F71 */\n    line-height: 1.2;\n}\n\n#wemd h2 .prefix,\n#wemd h2 .suffix {\n    display: none;\n}\n\n/* \n * \u4E09\u7EA7\u6807\u9898 - \u50CF\u4E66\u672C\u7684\u5C0F\u8282\n * \u5496\u5561\u8272\u6587\u5B57 + \u5DE6\u4FA7\u88C5\u9970\n */\n#wemd h3 {\n    margin-top: 40px;\n    margin-bottom: 20px;\n}\n\n#wemd h3 .content {\n    font-size: 18px;\n    font-weight: bold;\n    color: #8D5B4C;\n    display: inline-block;\n    padding-left: 10px;\n    border-left: 4px solid #D98C45;\n    /* \u7425\u73C0\u9EC4 */\n}\n\n#wemd h3 .prefix,\n#wemd h3 .suffix {\n    display: none;\n}\n\n/* \n * \u56DB\u7EA7\u6807\u9898 - \u6781\u7B80\u4E0B\u5212\u7EBF\n */\n#wemd h4 {\n    margin-top: 30px;\n    margin-bottom: 15px;\n    text-align: left;\n}\n\n#wemd h4 .content {\n    display: inline-block;\n    font-size: 16px;\n    font-weight: bold;\n    color: #B33D25;\n    border-bottom: 2px solid #F2C94C;\n    /* \u4EAE\u9EC4\u7EBF\u6761 */\n    padding-bottom: 2px;\n}\n\n#wemd h4 .prefix,\n#wemd h4 .suffix {\n    display: none;\n}\n\n/* \u5217\u8868 - \u7ECF\u5178\u7684\u5B9E\u5FC3\u65B9\u70B9 */\n#wemd ul {\n    list-style-type: square;\n    padding-left: 20px;\n    margin: 20px 0;\n    color: #D98C45;\n}\n\n#wemd ul li {\n    margin-bottom: 12px;\n    line-height: 1.8;\n}\n\n#wemd li section {\n    color: #5D4037;\n    font-size: 16px;\n}\n\n/* \u6709\u5E8F\u5217\u8868 */\n#wemd ol {\n    list-style-type: decimal;\n    padding-left: 20px;\n    margin: 20px 0;\n    color: #B33D25;\n    font-weight: bold;\n    font-family: serif;\n    /* \u6570\u5B57\u4E5F\u7528\u886C\u7EBF\u4F53\uFF0C\u5F88\u6709\u5473\u9053 */\n}\n\n#wemd ol li {\n    margin-bottom: 12px;\n    line-height: 1.8;\n}\n\n#wemd ol li section {\n    color: #5D4037;\n    font-weight: normal;\n    font-size: 16px;\n}\n\n#wemd ul ul {\n    list-style-type: circle;\n    color: #8D5B4C;\n    margin-top: 8px;\n}\n\n#wemd ol ol {\n    list-style-type: lower-roman;\n    color: #B33D25;\n}\n\n/* \n * \u5F15\u7528 - \u6CDB\u9EC4\u7684\u65E7\u62A5\u7EB8\n * \u6DF1\u7C73\u8272\u80CC\u666F + \u68D5\u8272\u8FB9\u6846\n */\n#wemd .multiquote-1,\n#wemd .multiquote-2,\n#wemd .multiquote-3 {\n    margin: 36px 0;\n    padding: 24px;\n    background-color: #F7EED6;\n    /* \u6CDB\u9EC4\u80CC\u666F */\n    border-left: 3px solid #8D5B4C;\n    /* \u5496\u5561\u8272\u8FB9\u6846 */\n    border-radius: 2px;\n    overflow: visible !important;\n}\n\n#wemd .multiquote-1 p,\n#wemd .multiquote-2 p,\n#wemd .multiquote-3 p {\n    margin: 0;\n    color: #6D4C41;\n    font-size: 15px;\n    line-height: 1.8;\n    font-style: italic;\n}\n\n#wemd .multiquote-2 {\n    margin: 34px 0;\n    padding: 22px;\n    background: #FFF8E7;\n    border-left: 3px solid #D98C45;\n    border-radius: 2px;\n}\n\n#wemd .multiquote-3 {\n    margin: 32px 0;\n    padding: 20px;\n    background: #FFFBF0;\n    border-left: 2px solid #D98C45;\n    border-radius: 2px;\n}\n\n/* \u94FE\u63A5 - \u50CF\u662F\u624B\u5199\u7684\u4E0B\u5212\u7EBF */\n#wemd a {\n    color: #B33D25;\n    text-decoration: none;\n    border-bottom: 1px solid #B33D25;\n    font-weight: bold;\n    transition: opacity 0.2s;\n}\n\n/* \n * \u52A0\u7C97 - \u91CD\u70B9\u6807\u8BB0\n * \u50CF\u662F\u7528\u6DF1\u8272\u9A6C\u514B\u7B14\u5212\u8FC7\n */\n#wemd strong {\n    color: #B33D25;\n    font-weight: 900;\n    margin: 0 2px;\n}\n\n/* \u659C\u4F53 */\n#wemd em {\n    color: #D98C45;\n    font-style: italic;\n    font-weight: bold;\n}\n\n#wemd em strong {\n    color: #B33D25;\n}\n\n/* \u9AD8\u4EAE - \u6696\u9EC4\u80CC\u666F */\n#wemd mark {\n    background: rgba(242, 201, 76, 0.3);\n    color: #B33D25;\n    padding: 2px 4px;\n    border-radius: 2px;\n}\n\n/* \u5220\u9664\u7EBF */\n#wemd del {\n    text-decoration: line-through;\n    color: #8D5B4C;\n}\n\n/* \u5206\u9694\u7EBF - \u865A\u7EBF\u526A\u88C1\u7EBF */\n#wemd hr {\n    margin: 60px auto;\n    border: 0;\n    height: 1px;\n    border-top: 2px dashed #D98C45;\n    /* \u526A\u88C1\u7EBF\u98CE\u683C */\n    width: 100%;\n}\n\n/* \n * \u56FE\u7247 - \u8001\u7167\u7247\u98CE\u683C\n * \u52A0\u4E0A\u767D\u8272\u8FB9\u6846\u548C\u9634\u5F71\n */\n#wemd img {\n    display: block;\n    margin: 40px auto;\n    width: 95%;\n    /* \u7A0D\u5FAE\u7559\u70B9\u767D\u8FB9 */\n    border: 8px solid #fff;\n    /* \u6A21\u62DF\u7167\u7247\u767D\u8FB9 */\n    box-shadow: 0 10px 25px rgba(93, 64, 55, 0.15);\n    background: #fff;\n}\n\n#wemd figcaption {\n    font-size: 13px;\n    color: #8D5B4C;\n    margin-top: 15px;\n    font-style: italic;\n    font-family: serif;\n}\n\n/* \u884C\u5185\u4EE3\u7801 - \u5496\u5561\u8272\u5757 */\n#wemd p code,\n#wemd li code,\n#wemd td code,\n#wemd th code {\n    color: #5D4037;\n    background: #EFE6D5;\n    border: none;\n    padding: 2px 6px;\n    margin: 0 4px;\n    border-radius: 3px;\n    font-size: 14px;\n    font-family: serif;\n    /* \u4EE3\u7801\u4E5F\u7528\u886C\u7EBF\u4F53\uFF0C\u4FDD\u6301\u590D\u53E4\u611F */\n}\n\n/* \u4EE3\u7801\u5757 - \u590D\u53E4\u6253\u5B57\u673A\u914D\u8272 */\n/* \u4EE3\u7801\u5757 - \u6CE8\u610F\uFF1A\u4E0D\u8981\u8BBE\u7F6E color\uFF0C\u8BA9\u8BED\u6CD5\u9AD8\u4EAE\u4E3B\u9898\u63A7\u5236\u6587\u5B57\u989C\u8272 */\n#wemd pre code.hljs {\n    display: block;\n    padding: 20px;\n    background: #4A3B32;\n    /* \u6DF1\u5496\u5561\u80CC\u666F */\n    color: #E6CBB5;\n    /* \u9ED8\u8BA4\u5976\u8336\u8272\u6587\u5B57 */\n    font-size: 13px;\n    line-height: 1.6;\n    border-radius: 4px;\n    font-family: \"Courier New\", Courier, monospace;\n    /* \u6253\u5B57\u673A\u5B57\u4F53 */\n    overflow-x: auto;\n    white-space: pre;\n  min-width: max-content;\n    border: 4px solid #F7EED6;\n}\n\n/* \u4F18\u5316\u6DF1\u8272\u80CC\u666F\u4E0B\u7684\u8BED\u6CD5\u9AD8\u4EAE\u989C\u8272 - \u4F7F\u7528\u6696\u8272\u8C03\u9AD8\u5BF9\u6BD4\u5EA6\u989C\u8272 */\n#wemd pre code.hljs .hljs-comment,\n#wemd pre code.hljs .hljs-quote {\n    color: #A68B7A;\n}\n\n#wemd pre code.hljs .hljs-keyword,\n#wemd pre code.hljs .hljs-selector-tag {\n    color: #FFB84D;\n    font-weight: bold;\n}\n\n#wemd pre code.hljs .hljs-string,\n#wemd pre code.hljs .hljs-doctag {\n    color: #FFD4A3;\n}\n\n#wemd pre code.hljs .hljs-number,\n#wemd pre code.hljs .hljs-literal {\n    color: #C9A961;\n}\n\n#wemd pre code.hljs .hljs-title,\n#wemd pre code.hljs .hljs-section {\n    color: #F7EED6;\n    font-weight: bold;\n}\n\n#wemd pre code.hljs .hljs-built_in,\n#wemd pre code.hljs .hljs-builtin-name {\n    color: #E6CBB5;\n    font-weight: bold;\n}\n\n/* \u5982\u679C\u6CA1\u6709\u8BED\u6CD5\u9AD8\u4EAE\uFF0C\u8BBE\u7F6E\u9ED8\u8BA4\u5976\u8336\u8272 */\n#wemd pre code:not(.hljs) {\n    color: #E6CBB5;\n    background: #4A3B32;\n    border: 4px solid #F7EED6;\n}\n\n/* \u8868\u683C - \u590D\u53E4\u8D26\u5355 */\n#wemd table {\n    width: 100%;\n    border-collapse: collapse;\n    margin: 40px 0;\n    font-size: 14px;\n    border: 2px solid #8D5B4C;\n}\n\n#wemd table tr th {\n    background: #EFE6D5;\n    color: #4A3B32;\n    font-weight: bold;\n    border: 1px solid #8D5B4C;\n    padding: 12px 10px;\n    text-align: center;\n}\n\n#wemd table tr td {\n    border: 1px solid #8D5B4C;\n    padding: 12px 10px;\n    color: #5D4037;\n    background: #FFFBF0;\n}\n\n/* \u811A\u6CE8 */\n#wemd .footnote-word,\n#wemd .footnote-ref {\n    color: #B33D25;\n}\n\n#wemd .footnotes-sep {\n    border-top: 1px solid #D98C45;\n    padding-top: 20px;\n    margin-top: 60px;\n    font-size: 12px;\n    color: #8D5B4C;\n    text-align: center;\n    font-family: serif;\n}\n\n#wemd .footnote-num {\n    font-weight: bold;\n    color: #FFFBF0;\n    background-color: #D98C45;\n    border-radius: 50%;\n    width: 16px;\n    height: 16px;\n    display: inline-block;\n    text-align: center;\n    line-height: 16px;\n    font-size: 11px;\n    margin-right: 4px;\n}\n\n#wemd .footnote-item p {\n    color: #8D5B4C;\n    font-size: 12px;\n    margin: 4px 0;\n}\n\n/* \u516C\u5F0F */\n#wemd .block-equation > svg {\n    max-width: 100% !important;\n}\n\n#wemd .inline-equation > svg {\n    max-width: 100%;\n    vertical-align: middle;\n}\n\n/* \u63D0\u793A\u5757 - \u843D\u65E5\u80F6\u7247\u98CE\u683C */\n#wemd .callout {\n    margin: 36px 0;\n    padding: 24px;\n    background: #F7EED6;\n    border-left: 3px solid #8D5B4C;\n    border-radius: 2px;\n}\n\n#wemd .callout-title {\n    font-weight: bold;\n    margin-bottom: 10px;\n    color: #B33D25;\n    font-family: serif;\n    font-size: 15px;\n}\n\n#wemd .callout-icon { margin-right: 8px;\n    margin-right: 6px;\n}\n\n#wemd .callout-note { border-left-color: #8D5B4C; }\n#wemd .callout-tip { border-left-color: #D98C45; }\n#wemd .callout-important { border-left-color: #8D5B4C; }\n#wemd .callout-warning { border-left-color: #D98C45; }\n#wemd .callout-caution { border-left-color: #B33D25; }\n\n/* Imageflow CSS */\n#wemd .imageflow-layer1 {\n  margin-top: 1em;\n  margin-bottom: 0.5em;\n  /* white-space: normal; */\n  border: 0px none;\n  padding: 0px;\n  overflow: hidden;\n}\n\n#wemd .imageflow-layer2 {\n  white-space: nowrap;\n  width: 100%;\n  overflow-x: scroll;\n}\n\n#wemd .imageflow-layer3 {\n  display: inline-block;\n  word-wrap: break-word;\n  white-space: normal;\n  vertical-align: top;\n  width: 80%;\n  margin-right: 10px;\n  flex-shrink: 0;\n}\n\n#wemd .imageflow-img {\n  display: block;\n  width: 100%;\n  height: auto;\n  max-height: 300px;\n  object-fit: contain;\n  border-radius: 4px;\n}\n\n#wemd .imageflow-caption {\n  text-align: center;\n  margin-top: 0px;\n  padding-top: 0px;\n  color: #888;\n}\n";
